import { WindowConf, WindowType } from '@droid/android';
import { useProxyWatch, useTranslation } from '@fanfanlo';
import {
  Box,
  MenuItem,
  Select,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { RequiredLabel, OptionalLabel } from './WindowConfUI';

export interface BasicInfoSectionProps {
  windowConf: WindowConf;
  hideTag?: boolean;  // 是否隐藏 tag 字段
}

/**
 * BasicInfoSection - 基本信息编辑区域
 *
 * 编辑字段：
 * - windowType: 窗口类型
 * - tag: 窗口标识
 * - description: 窗口说明
 * - windowId: 窗口 ID (只读)
 */
export function BasicInfoSection({ windowConf, hideTag = false }: BasicInfoSectionProps) {
  const { t } = useTranslation('homepage/components/android-float/window/content');
  const [windowType] = useProxyWatch(windowConf, 'windowType', windowConf.windowType);
  const [tag] = useProxyWatch(windowConf, 'tag', windowConf.tag);
  const [description] = useProxyWatch(windowConf, 'description', windowConf.description || '');
  const [windowId] = useProxyWatch(windowConf, 'windowId', windowConf.windowId);

  console.log('BasicInfoSection: render windowType:', windowType, 'tag:', tag, 'hideTag:', hideTag);

  return (
    <Stack spacing={2}>
      {/* 窗口类型 */}
      {/* <Box>
        <RequiredLabel label="窗口类型" />
        <Select
          value={windowType}
          onChange={(e) => {
            console.log('BasicInfoSection: windowType changed to', e.target.value);
            windowConf.windowType = e.target.value as WindowType;
          }}
          size="small"
          fullWidth
        >
          <MenuItem value={WindowType.Float}>浮窗 (Float)</MenuItem>
          <MenuItem value={WindowType.Dialog}>对话框 (Dialog)</MenuItem>
          <MenuItem value={WindowType.System}>系统窗口 (System)</MenuItem>
        </Select>
      </Box> */}

      {/* 窗口标识 - 根据 hideTag 决定是否显示 */}
      {!hideTag && (
        <Box>
          <RequiredLabel label={t('BasicInfoSection.windowTag')} />
          <TextField
            value={tag}
            onChange={(e) => {
              console.log('BasicInfoSection: tag changed to', e.target.value);
              windowConf.tag = e.target.value;
            }}
            size="small"
            fullWidth
          />
        </Box>
      )}

      {/* 窗口说明 */}
      <Box>
        <OptionalLabel label={t('BasicInfoSection.windowDescription')} />
        <TextField
          value={description}
          onChange={(e) => {
            console.log('BasicInfoSection: description changed to', e.target.value);
            windowConf.description = e.target.value;
          }}
          size="small"
          fullWidth
          multiline
          rows={2}
        />
      </Box>

      {/* 窗口 ID（只读） */}
      <Box>
        <Typography variant="body2" sx={{ fontWeight: 'bold', mb: 0.5 }}>
          {t('BasicInfoSection.windowIdLabel')}
        </Typography>
        <TextField
          value={windowId}
          disabled
          size="small"
          fullWidth
        />
      </Box>
    </Stack>
  );
}
